import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, readdir, rm, stat, utimes, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { tmpdir } from 'node:os';
import { join, basename } from 'node:path';
import { indexComposerSources } from './d274-index.mjs';
import { EntryStore } from './d274-entry-store.mjs';

const root = await mkdtemp(join(tmpdir(), 'sophp-entry-cache-controls-'));
const directory = join(root, '.cache');
const paths = ['A', 'B', 'C'].map((name) => join(root, 'src', name + '.php'));
const report = { status: 'running', checks: [] };
const check = async (name, fn) => { await fn(); report.checks.push(name); process.stdout.write('PASS ' + name + '\n'); };
const payload = (source) => ({ source, valid: true, unicode: '中文🙂"\\\n'.repeat(10000) });
let restored = []; let parsed = [];
const options = { readConcurrency: 3, onSource: ({ path, source }) => { parsed.push(path); return payload(source); },
  cache: { directory, version: 'entry-controls-v1', restore: (value, source) => {
    restored.push(source.path); return value.valid === true && value.source === `<?php class ${basename(source.path, '.php')} {}`;
  } } };
const run = async (extra = {}) => { restored = []; parsed = []; return indexComposerSources(root, { ...options, ...extra }); };
let cacheFile;
const manifest = async () => JSON.parse(await readFile(cacheFile, 'utf8'));
const entryPath = (m, entry) => join(cacheFile + '.entries', m.generation, entry.payloadHash + '.json');
try {
  await mkdir(join(root, 'src'));
  await writeFile(join(root, 'composer.json'), JSON.stringify({ autoload: { 'psr-4': { 'App\\': 'src/' } } }));
  await Promise.all(paths.map((path) => writeFile(path, `<?php class ${basename(path, '.php')} {}`)));
  await check('cold Unicode entries are stored outside metadata and warm restore preserves path order', async () => {
    assert.equal((await run()).cached, 0);
    cacheFile = join(directory, (await readdir(directory)).find((name) => name.endsWith('.json')));
    const m = await manifest(); assert.equal(m.schema, 2);
    assert.ok((await stat(cacheFile)).size < 3000);
    for (const entry of Object.values(m.entries)) assert.equal(Object.hasOwn(entry, 'payload'), false);
    assert.equal((await run()).cached, 3); assert.deepEqual(restored, paths); assert.deepEqual(parsed, []);
    const store = await EntryStore.load(cacheFile, root, options.cache.version);
    assert.deepEqual(await store.payload(store.previous.get(paths[0])), payload('<?php class A {}')); await store.dispose();
  });
  await check('fully warm metadata and generation remain unchanged', async () => {
    const old = await readFile(cacheFile, 'utf8'); const fixed = new Date('2001-02-03T04:05:06Z');
    await utimes(cacheFile, fixed, fixed); assert.equal((await run()).cached, 3);
    assert.equal((await stat(cacheFile)).mtimeMs, fixed.getTime()); assert.equal(await readFile(cacheFile, 'utf8'), old);
  });
  await check('payload checksum corruption rebuilds exactly one file and prunes replaced generation', async () => {
    const m = await manifest(); await writeFile(entryPath(m, m.entries[paths[0]]), '{broken');
    const result = await run(); assert.equal(result.cached, 2); assert.deepEqual(parsed, [paths[0]]);
    assert.equal((await run()).cached, 3);
    const current = await manifest(); assert.notEqual(current.generation, m.generation);
    assert.deepEqual(await readdir(cacheFile + '.entries'), [current.generation]);
  });
  await check('adapter-level payload rejection rebuilds one file with outer hash kept valid', async () => {
    const m = await manifest(); const entry = m.entries[paths[1]];
    const value = JSON.parse(await readFile(entryPath(m, entry), 'utf8')); value.valid = false;
    const text = JSON.stringify(value); entry.payloadHash = createHash('sha256').update(text).digest('hex'); entry.payloadBytes = Buffer.byteLength(text);
    await writeFile(entryPath(m, entry), text); await writeFile(cacheFile, JSON.stringify(m));
    const result = await run(); assert.equal(result.cached, 2); assert.deepEqual(parsed, [paths[1]]);
  });
  await check('cancelled source production preserves manifest and leaves no staging directories', async () => {
    const old = await readFile(cacheFile, 'utf8'); let count = 0;
    const result = await run({ shouldContinue: () => count < 2,
      onSource: ({ source }) => { count++; return payload(source); }, cache: { ...options.cache, restore: () => false } });
    assert.equal(result.complete, false); assert.ok(result.warnings.includes('Project indexing was cancelled.'));
    assert.equal(await readFile(cacheFile, 'utf8'), old);
    assert.deepEqual(await readdir(cacheFile + '.entries'), [(await manifest()).generation]);
  });
  await check('commit contention preserves published cache and cleans private staging', async () => {
    const old = await readFile(cacheFile, 'utf8'); await writeFile(cacheFile + '.lock', 'active-control');
    try {
      const result = await run({ cache: { ...options.cache, restore: () => false } });
      assert.equal(result.complete, true); assert.ok(result.warnings.includes('Persistent index cache could not be written.'));
      assert.equal(await readFile(cacheFile, 'utf8'), old);
      assert.deepEqual(await readdir(cacheFile + '.entries'), [(await manifest()).generation]);
    } finally { await rm(cacheFile + '.lock'); }
  });
  await check('legacy schema 1 payloads migrate without reparsing source', async () => {
    const m = await manifest();
    const entries = {};
    for (const [path, entry] of Object.entries(m.entries)) {
      const { payloadHash, payloadBytes, ...metadata } = entry;
      entries[path] = { ...metadata, payload: JSON.parse(await readFile(entryPath(m, entry), 'utf8')) };
    }
    await writeFile(cacheFile, JSON.stringify({ schema: 1, root, version: options.cache.version, entries }));
    await rm(cacheFile + '.entries', { recursive: true });
    assert.equal((await run()).cached, 3); assert.deepEqual(parsed, []); assert.equal((await manifest()).schema, 2);
  });
  await check('unsafe payload identity is rejected before reads and rebuilds one entry', async () => {
    const m = await manifest(); m.entries[paths[0]].payloadHash = '../../outside';
    await writeFile(cacheFile, JSON.stringify(m));
    const result = await run(); assert.equal(result.cached, 2); assert.deepEqual(parsed, [paths[0]]);
    assert.ok(result.warnings.some((warning) => warning.includes('was rejected and rebuilt')));
  });
  await check('malformed manifest tail cannot partially restore', async () => {
    const m = await readFile(cacheFile, 'utf8'); await writeFile(cacheFile, m + 'invalid-tail');
    assert.equal((await run()).cached, 0); assert.deepEqual(parsed, paths);
  });
  await check('deleted source drops its payload from the committed generation', async () => {
    await rm(paths[2]); const result = await run(); assert.equal(result.cached, 2);
    const m = await manifest(); assert.deepEqual(Object.keys(m.entries), paths.slice(0, 2));
    assert.equal((await readdir(join(cacheFile + '.entries', m.generation))).length, 2);
    assert.deepEqual(await readdir(cacheFile + '.entries'), [m.generation]);
  });
  await check('cancellation during cache commit preserves old manifest', async () => {
    const old = await readFile(cacheFile, 'utf8'); const store = await EntryStore.load(cacheFile, root, options.cache.version);
    let calls = 0;
    try { assert.equal(await store.commit(new Map(store.previous), () => ++calls < 4), false); }
    finally { await store.dispose(); }
    assert.equal(await readFile(cacheFile, 'utf8'), old);
    assert.deepEqual(await readdir(cacheFile + '.entries'), [(await manifest()).generation]);
  });
  await check('concurrent commit contender cannot publish an incomplete generation', async () => {
    const stores = await Promise.all([EntryStore.load(cacheFile, root, options.cache.version), EntryStore.load(cacheFile, root, options.cache.version)]);
    try {
      const outcomes = await Promise.allSettled(stores.map((store) => store.commit(new Map(store.previous))));
      assert.equal(outcomes.filter((value) => value.status === 'fulfilled' && value.value).length, 1);
      assert.equal(outcomes.filter((value) => value.status === 'rejected').length, 1);
      assert.equal((await run()).cached, 2);
      assert.deepEqual(await readdir(cacheFile + '.entries'), [(await manifest()).generation]);
    } finally { await Promise.all(stores.map((store) => store.dispose())); }
  });
  report.status = 'passed';
} catch (error) { report.status = 'failed'; report.error = String(error.stack); throw error; }
finally {
  await writeFile(process.env.SOPHP_ENTRY_CONTROL_REPORT, JSON.stringify(report, null, 2));
  await rm(root, { recursive: true, force: true });
}

