import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir, hostname } from 'node:os';
import { join, basename } from 'node:path';
import { indexComposerSources } from './d274-index.mjs';

const report = { status: 'running', checks: [] };
async function fixture(action) {
  const root = await mkdtemp(join(tmpdir(), 'sophp-entry-edges-'));
  try {
    await mkdir(join(root, 'src'));
    await writeFile(join(root, 'composer.json'), JSON.stringify({ autoload: { 'psr-4': { 'App\\': 'src/' } } }));
    const paths = ['A', 'B', 'C'].map((name) => join(root, 'src', name + '.php'));
    await Promise.all(paths.map((path) => writeFile(path, `<?php class ${basename(path, '.php')} {}`)));
    const options = { onSource: ({ path }) => ({ identity: basename(path), valid: true }),
      cache: { directory: join(root, 'cache'), version: 'edge-v1', restore: () => true } };
    const index = (extra) => indexComposerSources(root, { ...options, ...extra });
    await index();
    const path = join(options.cache.directory, (await readdir(options.cache.directory)).find((name) => name.endsWith('.json')));
    await action({ root, paths, options, path, index });
  } finally { await rm(root, { recursive: true, force: true }); }
}
async function check(name, action) {
  try { await fixture(action); report.checks.push({ name, passed: true }); }
  catch (error) { report.checks.push({ name, passed: false, error: String(error.stack) }); }
}
await check('serialization failure preserves the complete prior manifest (existing index contract)', async ({ index, options, path }) => {
  const before = await readFile(path, 'utf8'); let count = 0; const cyclic = {}; cyclic.self = cyclic;
  await index({ cache: { ...options.cache, restore: () => false }, onSource: () => ++count === 3 ? cyclic : { valid: true } });
  assert.equal(await readFile(path, 'utf8'), before);
});
await check('schema 2 metadata cannot bypass the payload checksum with an inline payload field', async ({ index, path, paths, options }) => {
  const data = JSON.parse(await readFile(path, 'utf8')); data.entries[paths[0]].payload = { injected: true };
  await writeFile(path, JSON.stringify(data));
  const seen = [];
  await index({ cache: { ...options.cache, restore: (payload) => { seen.push(payload); return true; } } });
  assert.equal(seen.some((payload) => payload?.injected === true), false);
});
await check('a commit lock with a dead local owner is recoverable', async ({ index, path, options }) => {
  // 2147483647 exceeds Linux pid_max in this controlled environment.
  assert.throws(() => process.kill(2147483647, 0), { code: 'ESRCH' });
  await writeFile(path + '.lock', JSON.stringify({ hostname: hostname(), pid: 2147483647, token: 'dead-control' }));
  const result = await index({ cache: { ...options.cache, restore: () => false }, onSource: () => ({ changed: true }) });
  assert.equal(result.warnings.includes('Persistent index cache could not be written.'), false);
});
report.status = report.checks.every((entry) => entry.passed) ? 'passed' : 'failed';
await writeFile(process.env.SOPHP_ENTRY_EDGE_REPORT, JSON.stringify(report, null, 2));
process.stdout.write(JSON.stringify(report, null, 2) + '\n');
if (report.status === 'failed') process.exitCode = 1;

