import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';
import { PhpSyntaxParser } from '../packages/parser/dist/index.js';
import { SemanticWorkspace } from '../packages/semantic/dist/index.js';

const count = 128;
const parser = await PhpSyntaxParser.create({ coreWasmPath: 'dist/web-tree-sitter.wasm', phpWasmPath: 'dist/tree-sitter-php.wasm' });
const cold = new SemanticWorkspace(parser);
const warm = new SemanticWorkspace(parser);
const report = { kind: 'allocation-shape-observation-only', files: count, executedWorkspacePhp: false };
try {
  for (let index = 0; index < count; index++) {
    const uri = `file:///AccessorProbe/Item${index}.php`;
    cold.update(uri, `<?php namespace AccessorProbe; final class Item${index} { public function getName(): string { return 'name'; } }`);
    assert.equal(warm.restoreDeclaration(cold.snapshotForPersistence(uri), uri), true);
  }
  assert.equal(warm.deferredImplementationCount(), count);
  assert.ok(warm.files instanceof Map, 'Diagnostic requires the actual compiled workspace file Map.');
  const functions = new Set(); const byField = new Map(); let descriptors = 0;
  for (const file of warm.files.values()) {
    for (const [field, descriptor] of Object.entries(Object.getOwnPropertyDescriptors(file))) {
      if (!descriptor.get) continue;
      descriptors++; functions.add(descriptor.get);
      let identities = byField.get(field); if (!identities) byField.set(field, identities = new Set()); identities.add(descriptor.get);
    }
  }
  report.deferredFiles = warm.deferredImplementationCount(); report.accessorDescriptors = descriptors;
  report.distinctGetterFunctions = functions.size;
  report.distinctFunctionsByField = Object.fromEntries([...byField].map(([field, values]) => [field, values.size]));
  report.scope = 'Counts actual function identities; does not estimate bytes, force GC, take heap snapshots or establish scale RSS/latency.';
  report.status = 'observed';
} finally { cold.dispose(); warm.dispose(); parser.dispose(); }
await writeFile(process.env.SOPHP_GETTER_COUNT_REPORT, JSON.stringify(report, null, 2));
process.stdout.write(JSON.stringify(report, null, 2) + '\n');
